# -*- coding: utf-8 -*-
"""Текстовый выпуск 5 (план E006): тело страницы lessons/ep05.html — участники дорожного движения.

Собирается tools/build.py: build импортирует этот модуль и вызывает render().
Части разделены маркером <!--AFTER-TICKETS-->: всё после него сайт показывает под билетами."""
from pdd.lessonkit import chat, lq, fig, gl
from figs import fig_roles, fig_outside, fig_boarding

P = []
P.append(chat(
    ("a", "Словарь дорог закрыли. Теперь, как обещали, — кто по ним движется. Тут-то всё очевидно: водители и пешеходы."),
    ("m", "И пассажиры. Ну и гаишник с палкой."),
    ("t", "Гаишник с палкой участником как раз не будет. А «очевидные» водитель и пешеход в законе устроены хитрее, чем кажется. Начнём с общего слова.")))

# ---------- 1. Участник ----------
P.append('<h2 id="uchastnik">1. Участник дорожного движения</h2>')
P.append(lq("Участник дорожного движения – лицо, непосредственно участвующее в процессе дорожного движения в качестве водителя, пассажира или пешехода.", "ст. 5, п. 61"))
P.append('<p>Список <b>закрытый</b>: ролей три — водитель, пассажир, пешеход. Кто не подходит ни под одну, тот по этому определению не участник. Остальной закон обращается к участникам постоянно: «ни один из участников дорожного движения не должен въезжать» на закрытый переезд (ст. 39, п. 1 «б»), уступить дорогу должен «участник» и т. д. Поэтому важно, кто именно в этот круг входит.</p>')
P.append('<p>Слово «непосредственно» отсекает тех, кто только организует движение или стоит в стороне. А само ' + gl("дорожное движение", "«отношения, возникающие при передвижении или нахождении на дороге участников дорожного движения с помощью транспортных средств или без таковых» (ст. 5, п. 60)") + ' включает и <i>нахождение</i> на дороге: стоящий на обочине пешеход — тоже участник.</p>')
P.append('<h3>Где список не сходится</h3>')
P.append('<p>Через 34 пункта тот же закон вводит четвёртую фигуру:</p>')
P.append(lq("Пользователь трассой для катания – участник дорожного движения, использующий для пешего хода и катания склоны или (и) дороги (трассы) для катания по снегу/льду", "ст. 5, п. 95"))
P.append('<p>Лыжник на склоне назван участником, хотя ни водителем, ни пассажиром, ни пешеходом в смысле п. 61 он не значится. <span class="unsure">Наш вывод:</span> п. 95 дописан позже (горнолыжные трассы) и с п. 61 не согласован. На экзамене это не встретится, но показывает, что «закрытые» списки закона надо проверять.</p>')

# ---------- 2. Водитель ----------
P.append('<h2 id="voditel">2. Водитель</h2>')
P.append(lq("Водитель – физическое лицо, управляющее транспортным средством. К водителям приравниваются погонщики. При осуществлении обучения практическому вождению транспортным средством (учебной езды) к водителям приравниваются инструкторы-преподаватели.", "ст. 5, п. 49"))
P.append('<p>Разберём по словам.</p><ol class="parts">'
         '<li><b>«Физическое лицо»</b> — человек, а не фирма-владелец.</li>'
         '<li><b>«Управляющее»</b> — решает действие, а не документ. О правах, страховке, возрасте в определении ни слова. <span class="unsure">Наш вывод:</span> человек без прав за рулём — всё равно водитель, и все обязанности водителя на нём. Велосипедист тоже водитель: велосипед — транспортное средство (это следующий урок).</li>'
         '<li><b>Погонщик</b> — ' + gl("погонщик", "«работник, погоняющий, ведущий или сопровождающий по дорогам вьючных, упряжных или верховых животных» (ст. 5, п. 36)") + '. Без всякой машины он водитель.</li>'
         '<li><b>Инструктор</b> приравнен к водителю только «при осуществлении обучения» — во время учебной езды. Вне её он обычный пассажир или водитель своей машины.</li></ol>')
P.append('<p>Последняя фраза п. 49 добавляет ещё одну группу: водителями являются также лица, допущенные Агентством по оказанию услуг МВД ко второму этапу практического экзамена, — пока они в нём участвуют. Экзаменуемый за рулём — водитель, хотя прав у него ещё нет (<span class="unsure">наш вывод</span>: со всеми обязанностями водителя).</p>')
P.append(chat(("m", "А ученик в автошколе? Его в списке нет. Значит, отвечает инструктор?"),
              ("t", "Ученика нет среди «приравненных», потому что он и так водитель — он же управляет. Закон просто добавил к нему второго водителя.")))
P.append('<p><span class="unsure">Наш вывод</span> из первой фразы: ученик за рулём — водитель. Закон этого прямо не пишет, но и исключения для него не делает. Учебная езда на дорогах допускается только «на учебном транспортном средстве» и вместе с инструктором (ст. 61, п. 4), а сам закон там называет ученика «лицом (учеником)».</p>')
P.append('<p><b>Нестыковка.</b> Инструктор сидит рядом и, пока не жмёт на свои педали, не управляет. По определению пассажира (ниже) он пассажир — лицо в ТС, «не управляющее им». И одновременно приравнен к водителю. <span class="unsure">Наш вывод:</span> специальное правило п. 49 сильнее общего п. 34, так что во время учебной езды инструктор отвечает как водитель.</p>')

# ---------- 3. Пешеход ----------
P.append('<h2 id="peshehod">3. Пешеход</h2>')
P.append(lq("Пешеход – участник дорожного движения, передвигающийся пешком либо использующий для передвижения роликовые коньки, роликовую доску, санки или иное подобное средство. К пешеходам приравниваются лица, везущие детскую или инвалидную коляску либо транспортное средство малых размеров без двигателя, а также лица, ведущие велосипед, мопед или мотоцикл, а равно лица с ограниченными возможностями, передвигающиеся в инвалидных колясках.", "ст. 5, п. 87"))
P.append('<p>Пешеход — не только тот, кто идёт. Два круга:</p><ul>'
         '<li><b>Сами пешеходы:</b> пешком, на роликах, на роликовой доске, на санках «или ином подобном средстве».</li>'
         '<li><b>Приравненные:</b> везущие детскую или инвалидную коляску или маленькое ТС без двигателя; <b>ведущие</b> велосипед, мопед, мотоцикл; люди в инвалидных колясках.</li></ul>')
P.append('<p>Ключевое слово — «ведущие». Велосипедист, который слез и катит велосипед рядом, превращается в пешехода. Сел и поехал — снова водитель. Мопед и даже мотоцикл — то же самое: заглушил и катишь — пешеход. ' + gl("Мопед", "лёгкий мотоцикл до 45 км/ч; точное определение — в следующем уроке") + '.</p>')
P.append('<p>Ролики и самокаты закон упоминает ещё раз: такие пешеходы «не должны создавать угрозу передвигающимся по тротуарам или пешеходным дорожкам людям в инвалидных колясках или пешеходам» (ст. 24, п. 12). Самокат там назван прямо; в п. 87 его нет, он попадает в «иное подобное средство» — <span class="unsure">наш вывод</span>, и речь об обычном, без мотора.</p>')
P.append(fig(fig_roles(), "Рис. 1. Кто есть кто по ст. 5. Синие — водитель и пассажир, зелёные — приравненные к пешеходам, красный — не участник (п. 61 его не называет)."))

P.append('<h3>Следствие: по какой стороне идти за городом</h3>')
P.append('<p>Равенство с пешеходами — не просто ярлык. За городом обычный пешеход идёт навстречу машинам, чтобы видеть их. А для приравненных сделано исключение:</p>')
P.append(lq("В ненаселенных пунктах, на дорогах с двусторонним движением без разделительных полос и тротуаров пешеходы должны передвигаться по обочине навстречу движению, а в случае ее отсутствия или невозможности идти по ней – по левой стороне проезжей части дороги и в направлении, противоположном движению", "ст. 24, п. 5"))
P.append(lq("однако лица, ведущие велосипед, мопед или мотоцикл, а также лица с ограниченными возможностями, передвигающиеся в инвалидных колясках, должны занимать правую сторону проезжей части дороги.", "ст. 24, п. 5"))
P.append('<p>(В середине пункта есть оговорка: обычный пешеход может идти и по правой стороне по ходу движения, если в конкретной ситуации это безопаснее.)</p><p>Почему для ведущих велосипед правило другое — закон не объясняет. <span class="unsure">Наш вывод:</span> велосипед или коляску неудобно и опасно разворачивать против потока, а по правой стороне они идут вместе с ним, как ехали бы. Это ровно билеты № 941 и 942. Для колясок есть ещё одно послабление:</p>')
P.append(lq("Действие пункта 2 настоящей статьи не распространяется на лиц с ограниченными возможностями, передвигающихся в инвалидных колясках. Они вправе передвигаться по краю проезжей части дороги в любых случаях.", "ст. 24, п. 3"))
P.append('<p>Обычный пешеход обязан пользоваться тротуаром, дорожкой или обочиной, если они есть (ст. 24, п. 2). Человек в коляске — нет: край проезжей части ему разрешён «в любых случаях», даже при свободном тротуаре.</p>')
P.append(fig(fig_outside(), "Рис. 2. Загородная дорога без тротуара и разделительной полосы. Пешеход — по обочине навстречу машинам; ведущий велосипед и человек в коляске — по правой стороне проезжей части (ст. 24, п. 5)."))
P.append('<p><b>Неясность.</b> П. 5 говорит «правую сторону», но не говорит, в каком направлении по ней двигаться. <span class="unsure">Наш вывод:</span> правая сторона имеет смысл только по ходу движения, иначе это та же «левая» навстречу.</p>')

# ---------- 4. Пассажир ----------
P.append('<h2 id="passazhir">4. Пассажир</h2>')
P.append(lq("Пассажир – лицо, находящееся или входящее (поднимающееся) в транспортное средство или выходящее (спускающееся) из транспортного средства, но не управляющее им.", "ст. 5, п. 34"))
P.append('<p>Пассажиром становятся не в момент, когда сели, а <b>уже на подножке</b>: «входящее» и «выходящее» тоже пассажиры. Поэтому посадка и высадка регулируются как действия пассажира, а не пешехода:</p>')
P.append(lq("Пассажиры обязаны садиться в транспортное средство и выходить из него после его полной остановки, со стороны тротуара или обочины, а в случае невозможности – со стороны проезжей части дороги, если это не создает помех другим участникам дорожного движения.", "ст. 23, п. 1"))
P.append(fig(fig_boarding(), "Рис. 3. Посадка и высадка. Дверь со стороны дороги — запасной вариант: если со стороны тротуара или обочины нельзя и никому не мешаешь."))
P.append('<p>Две ступени: сначала только тротуар или обочина; проезжая часть — если первое невозможно <i>и</i> никому не мешаешь. Запрета «никогда со стороны дороги» нет, а «только за городом» нет тем более (билет № 811).</p>')
P.append(chat(("a", "Значит, если я выхожу из такси на проезжую часть, а сзади едет велосипедист, — это мне его ждать?"),
              ("t", "Тебе. Это ты не должна создавать помех. А водитель такси — не открывать тебе дверь в поток: пассажир — это ещё и тот, кто «выходящее».")))

# ---------- 5. Регулировщик ----------
P.append('<h2 id="reg">5. Регулировщик</h2>')
P.append(lq("Регулировщик – лицо, определенное законодательством Грузии, наделенное полномочиями по регулированию дорожного движения, которое в пределах своей компетенции вправе ограничить движение участника дорожного движения, изменить его направление или (и) приостановить его движение.", "ст. 5, п. 32"))
P.append('<p>Регулировщик стоит на дороге, но в списке п. 61 его нет: он <b>управляет участниками</b>, а не участвует. Его сигналы делают перекрёсток регулируемым (ст. 36, п. 2) — об этом в уроках о перекрёстках.</p>')
P.append('<p><b>Слабое место:</b> «лицо, определенное законодательством Грузии». Кто именно — полицейский, дорожный рабочий с флажком, школьный патруль, — статья 5 не говорит и отсылает к другим законам. По ней одной регулировщика в жилете не опознать; <span class="unsure">наш вывод</span> — на практике это патрульная полиция.</p>')

# ---------- Где текст не сходится ----------
P.append('<h2 id="flaws">Что в определениях неладно</h2>')
P.append('<ul class="flaws">'
         '<li>П. 61 перечисляет три роли, а п. 95 добавляет четвёртую — «пользователя трассой для катания».</li>'
         '<li>Ученик в п. 49 не назван; водителем его делает только первая фраза (наш вывод).</li>'
         '<li>Инструктор по п. 34 — пассажир (не управляет), по п. 49 — приравнен к водителю.</li>'
         '<li>Регулировщик определён через отсылку («определенное законодательством») — круг лиц из ст. 5 не виден.</li>'
         '<li>Ст. 24, п. 5 не указывает направление движения по правой стороне для ведущих велосипед.</li>'
         '</ul>')

# ---------- Ситуации ----------
P.append('<h2 id="sit">Две ситуации</h2>')
P.append('<h3>Ситуация 1. Прокол за городом</h3>')
P.append(chat(("a", "Еду на велосипеде из Мцхеты, прокол. Тротуара нет, обочина узкая. Пойду пешком по левой стороне навстречу машинам — так же безопаснее?"),
              ("t", "Для пешехода — да. Но ты ведёшь велосипед: тебе правая сторона проезжей части.")))
P.append('<p>Разбор: ведущая велосипед — пешеход (ст. 5, п. 87), но для неё ст. 24, п. 5 делает исключение: «правую сторону проезжей части дороги». Поехала дальше — снова водитель велосипеда со своими правилами (ст. 43).</p>')
P.append('<h3>Ситуация 2. Учебная машина</h3>')
P.append(chat(("m", "Друг учится с инструктором. Говорит: «Я за рулём не водитель, отвечает инструктор»."),
              ("t", "Водители оба. Инструктор — потому что закон его приравнял, твой друг — потому что управляет.")))
P.append('<p>Разбор: «Водитель – физическое лицо, управляющее транспортным средством» (ст. 5, п. 49) — первая фраза относится к ученику (наш вывод); инструктор приравнен при учебной езде (там же).</p>')
P.append('<p class="note info">Дальше — билеты из экзаменационной базы: посадка пассажиров (№ 811) и сторона дороги для ведущего велосипед и для человека в коляске (№ 941, 942). Определений участников в базе нет — их проверяют наши вопросы после билетов.</p>')

P.append("<!--AFTER-TICKETS-->")
P.append(chat(("a", "Итого. Участников трое: водитель, пассажир, пешеход. Ведёшь велосипед — пешеход, едешь — водитель. Пассажир начинается на подножке."),
              ("m", "А регулировщик — не участник, а начальник. Понял."),
              ("t", "Следующий урок — про то, чем управляют водители: что такое транспортное средство, мопед, мотоцикл и почему трамвай не «механическое ТС».")))

BODY = "\n".join(P) + "\n"


def render() -> str:
    return BODY
